function event_spawn(e)
	eq.set_timer("depop",1200000);
end

function event_timer(e)
	eq.depop();
end

-- global script variables
local player_list = nil;
local player_list_count = nil;
local raid_group = nil;
local client_e = nil;
local entity_list = nil;

function event_click_door(e)
	-- populate the current entity list whenever someone clicks.
	entity_list = eq.get_entity_list();
	-- drop the door information into some local variables
	local door_id = e.door:GetDoorID();
	local open_type = entity_list:FindDoor(door_id):GetOpenType();
	client_e = e;
	-- make sure the player_list is clear
	player_list = nil;
	player_list_count = nil;
	raid_group = nil;
	-- only time we will use the raid value is if they are clicking on the Agnarr door
	-- otherwise, it is a group only port up.
	local raid = e.self:GetRaid();
	if (raid.valid) then
		player_list = raid;
		player_list_count = raid:RaidCount();
		raid_group = raid:GetGroup(e.self);
	else
		-- if group is not valid, it is a single player click up
		local group = e.self:GetGroup();
		if (group.valid) then
			player_list = group;
			player_list_count = group:GroupCount();
		end
	end

	-- Agnarr Tower aka electric penis
	if (door_id == 51) then
		-- check if the person clicking has the Symbol of Torden item id:9433 or has GM status of 80+ with the GM flag on.
		-- the point of checking both status and GM flag is so a dev with status > 80 can still pretend to be a non-GM.
		-- by using the status, we ensure someone cannot bypass the check by another GM using "#gm on" on a player.
		if (e.self:Admin() >= 80 and e.self:GetGM()) then
			PortIntoTower(e.self:GetX(), e.self:GetY(), e.self:GetZ(), 100, -765, -1735, 1270, 0, false);
		elseif (e.self:HasItem(9433)) then
			PortIntoTower(e.self:GetX(), e.self:GetY(), e.self:GetZ(), 100, -765, -1735, 1270, 0, false);
		else
			SendGargoyles(209024);
		end
	-- the four corner towers all use the same key and it can be on the keyring
	elseif (door_id == 61 or door_id == 63 or door_id == 65 or door_id == 67) then
		-- check if the Ring of Torden item id: 9425 is on the keyring
		local key_found = false;
		if (e.self:KeyRingCheck(9425)) then
			key_found = true;
		-- if it is not on the keyring check for them to have the item.
		elseif e.self:HasItem(9425) then
			key_found = true;
			-- add it tot he keyring
			e.self:KeyRingAdd(9425);
		-- allow a GM to click up
		elseif (e.self:Admin() >= 80 and e.self:GetGM()) then
			key_found = true;
		end
		-- Southeast tower
		if (door_id == 61) then
			-- did the player have the key?
			if (key_found) then
				PortIntoTower(e.self:GetX(), e.self:GetY(), e.self:GetZ(), 50, 85, 145, 635, 128, true);
			else
				SendGargoyles(209110);
			end
		-- Southwest tower
		elseif (door_id == 63) then
			-- did the player have the key?
			if (key_found) then
				PortIntoTower(e.self:GetX(), e.self:GetY(), e.self:GetZ(), 50, -830, -865, 1375, 128, true);
			else
				SendGargoyles(209111);
			end
		-- Northwest tower
		elseif (door_id == 65) then
			-- did the player have the key?
			if (key_found) then
				PortIntoTower(e.self:GetX(), e.self:GetY(), e.self:GetZ(), 50, -350, -2200, 1955, 255, true);
			else
				SendGargoyles(209112);
			end
		-- Northeast tower
		elseif (door_id == 67) then
			-- did the player have the key?
			if (key_found) then
				PortIntoTower(e.self:GetX(), e.self:GetY(), e.self:GetZ(), 50, 150, -1220, 1120, 128, true);
			else
				SendGargoyles(209113);
			end
		end
	end
end

function SendGargoyles(npcid_to_aggro)
	-- get all the npcs 
	local npc_list = entity_list:GetNPCList();
	if (npc_list ~= nil) then
		for npc in npc_list.entries do
			if (npc:GetNPCTypeID() == npcid_to_aggro) then
				-- set aggro on person who clicked
				npc:AddToHateList(client_e.self,1);
			end
		end
	end
end

function PortIntoTower(cur_x, cur_y, cur_z, distance, dest_x, dest_y, dest_z, dest_h, group_only)
	-- player_list contains e.self:GetGroup or e.self:GetRaid or is nil for a single player
	-- if it is not nil then port up the group/raid as long as they are in range
	if (player_list ~= nil) then
		-- iterate through the player_list (it is 0 based)
		for i = 0, player_list_count - 1, 1 do
			local mob_v = player_list:GetMember(i);
			if (mob_v.valid and mob_v:IsClient()) then
				-- MovePC and GetAggroCount are client functions and group:GetMember returns a mob (raid:GetMember returns client)
				local client_v = mob_v:CastToClient();
				-- make sure we actually have a valid client
				if (client_v.valid) then
					-- if raid_group is not nil, we're in a raid, so we need to verify group number if group_only is true
					-- yes yes, this is a bit gross
					if (raid_group == nil or (not group_only or (raid_group ~= -1 and player_list:GetGroupNumber(i) == raid_group) or client_v:GetID() == client_e.self:GetID())) then
						-- check the distance and port them up if close enough
						if (client_v:CalculateDistance(cur_x, cur_y, cur_z) <= distance) then
							-- port the player up
							client_v:MovePC(209, dest_x, dest_y, dest_z, dest_h); -- Zone: bothunder
						end
					end
				end
			end
		end
	else
		-- port the player up
		client_e.self:MovePC(209, dest_x, dest_y, dest_z, dest_h); -- Zone: bothunder
	end
end

-- items: 62637
function event_say(e)
  if (e.other:Class() == "Ranger") then
    local qglobals = eq.get_qglobals(e.other);
    if ( qglobals["ranger_epic15_pre"] == "9" ) then
      if (e.message:findi("mera")) then
        e.self:Say("Mera? Sure, I know her. Bright girl. She left here a while ago with one of my new [" .. eq.say_link("sound capture jars") .. "]. She helped me design them. Bright girl. She ran off saying that she was going to find a great sound to capture in the jar. She was very excited. I hope she's safe. She said something about howling or something like that. I just didn't hear her properly. She's a very bright girl.");
      elseif (e.message:findi("sound capture jars")) then
        e.self:Say("The sound capture jar does exactly what it sounds like it does. If you use it properly, you can capture a sound in the jar for use later. I haven't worked out the details about how exactly you might use a sound, but I'm sure I'll figure something out. I have a few with me. They aren't part of my regular inventory, but I can sell you one if you need it for something. Seeing as you're a friend of Mera, I'll let you have it for cost, thirty platinum.");
      end
    end
  end
end

function event_trade(e)
  local qglobals = eq.get_qglobals(e.other);
  local item_lib = require('items');

  if ( qglobals["ranger_epic15_pre"] == "9" and item_lib.check_turn_in(e.trade, {platinum = 30})) then
    e.other:SummonItem(62637); -- Item: Sound Capture Jar
    e.self:Say("Here ya go. Good luck finding Mera.");
  end
end

-- everfrost/Kimber_Whitefoot.lua NPCID 30104
-- Warrior Epic 1.5
-- items: 60306, 60305

function event_say(e)
	local qglobals = eq.get_qglobals(e.other);
	if e.message:findi("hail") and qglobals["warrior_epic"] ~= nil and qglobals["warrior_epic"] >= "4" then
		e.self:Say("Yes, yes, you again. I had a chance to examine the vial you gave me. Quite an interesting substance, I must say. Scary though. Where did you say you found it? Never mind, it's not important. I made a potion out of the vial, but I can feel an evil presence within. I want to be rid of it, so you can have it back. Please don't come to me with anything like that again. I'm really not into dealing with spirits of such heinous design. Good luck.");
		e.other:SummonItem(60306); -- Item: Potion of Blackfall Spirit
	end
end

function event_trade(e)
	local item_lib = require("items");
	local qglobals = eq.get_qglobals(e.other);
	if qglobals["warrior_epic"] ~= nil and qglobals["warrior_epic"] >= "3" and item_lib.check_turn_in(e.trade, {item1 = 60305}) then -- Item: Sealed Vial of Blackfall Blood (from korbuk)
		e.self:Say("Great, wait out here for a while. I've got to make a trip into the frozen mountain of Permafrost, but I'll be out some time this evening. I should have enough time on my trek to examine the vial. I'll be back soon!");
		if qglobals["warrior_epic"] < "4" then
			eq.set_global("warrior_epic","4",5,"F");
		end
		eq.depop_with_timer();
	end
	item_lib.return_items(e.self, e.other, e.trade);
end

function event_waypoint_arrive(e)
	if e.wp == 9 then
		eq.depop_with_timer();
	end
end

function event_spawn(e)
eq.set_timer('depop', 300 * 1000);
end

function event_combat(e)
if e.joined then
if(not eq.is_paused_timer('depop')) then
			eq.pause_timer('depop');
		end
	else
		eq.resume_timer('depop');
	end
end

function event_timer(e)
if (e.timer == 'depop') then
eq.depop();
end
end

-- items: 18282, 2053, 2055, 1868, 2056, 1728, 2097, 2065, 2064
function event_say(e)
	if(e.other:GetFaction(e.self) < 2) then
		if(e.message:findi("hail")) then
			e.self:Emote("seems very intent on his current studies. After a few moments, the wyvern mutters, '...Hmmm?'");
		elseif(e.message:findi("not a master smith")) then
			e.self:Say("You must be the one to forge the weapon, " .. e.other:GetCleanName() .. ". Go and learn the art of the smith. Return only when you are a master and tell me you are ready. I will then tell you what must be done.");
		elseif(e.message:findi("am a master smith")) then
			e.self:Say("Good. The weapon is extremely complicated to construct, your skills will be tested perhaps beyond your abilities. The weapon is known as a Naginata. You need not be proficient in its use to build it. The Naginata is constructed of four major parts. The shaft, the blade, the fittings, and the hilt, or tsuba. No ordinary materials can hope to bind the dragons spirit. Special materials must be found.");
			e.other:SummonItem(18282); -- The Blade
		elseif(e.message:findi("make the shaft")) then
			e.self:Say("The shaft must be strong enough to withstand the effects of the spirit’s presence, yet flexible enough to be wielded properly. Of the few dragons that returned to us from the Ring of Scale, some brough back knowledge of a type of wood that may be sufficient. It is known as bronzewood. One can find it amidst one of the forests on the continent of Kunark. I am sure it is being used by one of the sentient races there.");
		elseif(e.message:findi("make the fitting")) then
			e.self:Say("The fittings are the most important part. The spirit itself will be held there partially. We’ll discuss this later, when you have all the other pieces in your possesion.");
		elseif(e.message:findi("make the hilt")) then
			e.self:Say("The tsuba is where most of the enchanment will lie. It must be forged seperately of another ore created to be the bane of the dragon. It is called chronium and was developed by the Kromzek with the aid of their blood-thirsty @#%$. You must forge the ore into a plate and then find a craftsman with the skill to carve a detailed mandala of draconic binding into it. This mandala will hold arcane power and restrain the spirit from destroying the weapon.");
		elseif(e.message:findi("chronium")) then
			e.self:Say("Chronium is a sacred ore used only by the higher ranked priests of Rallos Zek. You may be able to find some in the city of the Kromzek, Kael Drakkel. Perhaps in one of their temples. Forging it into a plate is simple. Heat the ore in a forge and shape it with a Forging Hammer, then temper it with a Flask of Water.");
		elseif(e.message:findi("make the blade")) then
			e.self:Say("The blade will be the most difficult piece for you to build. First of all, no mundane ore will do. Long ago, Veeshan sent a gift to us in the form of a meteor. This meteor holds the ore you must build the blade with. Once you have the ore, follow the instructions in this book and forge the blade. Don’t forget, when melting the ore, use the bone dust I gave you.");
		elseif(e.message:findi("craftsman")) then
			e.self:Say("Since the mandala is so detailed, only a craftsman trained specifically in these matters will do. I'm sure you're a fine smith but an adventurer like yourself wouldn't have time to fully master the skill needed to create the tsuba. Find one whose entire life is the art of creating these types of weapons. The craftsman will need a sketch of the mandala as well as the plate of chronium.");
		elseif(e.message:findi("mandala")) then
			e.self:Say("The type of mandala we need is a diagram laced with powerful arcane enchantment. You'll need to find a sketch of the correct mandala for the craftsman to go by as he carves it into the chronium plate. There is one place you may be able to find a sketch of a mandala powerful enough to bind Garzicor.");
		elseif(e.message:findi("place")) then
			e.self:Say("The ones that returned to us from the Ring of Scale told us of the Sarnak. These are hybrids of dragons and a sentient lizard race known as the Iksar. Whoever created them had to bind a dragon to his will or restrain it at some point. Perhaps this being or one of his brood still has a recording of the mandala. Once you have the Tsuba, Blade, and Shaft, return here and show them to me. I will then explain what must be done next.");
		elseif(e.message:findi("awaken")) then
			e.self:Say("First you must awaken his spirit by speaking where you found his corpse. You must say exactly this: 'You are one but two. Your vengeance shall find a home.'  Hopefully this will bring him to you. You must then hurry and splash the vial of Kromzek blood upon his ghostly form. The taste of the blood with bring him fully into existence. You must then do battle with him. If you defeat him, you will have split his being which will be represented by two more shades. Give them each a flawless diamond. He will comply and choose these gems as a phylactery. Once you have the dual phylactery, you need only combine them with the assembled naginata in a forge to create the Ethereal Bladed Naginata. Bring me the the weapon.");
		end
	end
end

function event_trade(e)
	local item_lib = require("items");

	if(item_lib.check_turn_in(e.trade, {item1 = 2053})) then -- Dragon Craft Urn (2nd combined version)
		e.self:Say("Hmm? What's this? Oh! You are the " .. e.other:GetRaceName() .. " who has been helping us with the nameless one. Well, not so nameless anymore. A part of Garzicor clings to this world, eager to wreak vengeance upon the giants who murdered him. We've decided that a weapon must be constructed, and the restless spirit of Garzicor must be bound to it. You must be the one to construct this weapon. This dust must be used in the forging of the weapon's blade. Are you a master smith, " .. e.other:GetCleanName() .. "?");
		e.other:QuestReward(e.self,0,0,0,0,2054,1000); -- Sanctified bone dust
	elseif(e.other:GetFaction(e.self) < 2 and item_lib.check_turn_in(e.trade, {item1 = 2055,item2 = 1868,item3 = 2056})) then -- Finished Tsuba, Bronzewood Staff, Finished Naginata Blade
		e.self:Emote("takes the staff, blade, and tsuba and looks them over. He says, 'Excellent craftsmanship. These will make a fine weapon. But one part remains to join all the pieces together. That is the fitings.' The Wyvern then hands you the items back along with a vial of blood and says, 'This vial of blood will allow you to awaken Garzicor's spirit.'");
		e.other:QuestReward(e.self,{items = {2426,2063}}); -- assembled Naginata, vial of Kromzek blood
	elseif(e.other:GetFaction(e.self) < 2 and item_lib.check_turn_in(e.trade, {item1 = 1728})) then -- Ethereal Bladed Naginata
		e.self:Say("You have succeeded " .. e.other:GetCleanName() .. ". Garzicor's spirit no longer calls to us from beyond. Now we ask that you do one more thing. You must wield this weapon against all giant kind to satiate Garzicor's thirst for vengeance. The Naginata has a special power against the Kromzek, they will fall easily before it. However, if you do not wish to, hand the weapon back to me and I'll give you an earring more worthy of a being of faith. If you are one of sorcerous powers, hand me the earring and I'll hand you a ring more suited to you.");
		e.other:Faction(430,10);  	--CoV
		e.other:Faction(436,2);  	-- Yelinak
		e.other:Faction(448,-5); 	-- Kromzek
		e.other:QuestReward(e.self,0,0,0,0,2097,10000); -- Ethereal Bladed Naginata (Eldriak's Verified Naginata)
	elseif(e.other:GetFaction(e.self) < 2 and item_lib.check_turn_in(e.trade, {item1 = 2097})) then -- Ethereal Bladed Naginata (Eldriak's Verified Naginata)
		e.self:Say("Tis sad to see that the weapon will not be wielded by its maker, but here is your earring. Wear it well.");
		e.other:QuestReward(e.self,0,0,0,0,2065); -- Sanctum Guardian's Earring
	elseif(e.other:GetFaction(e.self) < 2 and item_lib.check_turn_in(e.trade, {item1 = 2065})) then -- Sanctum Guardian's Earring
		e.self:Say("So you prefer the ring? Very well. May it serve you well, " .. e.other:GetCleanName() .. ".");
		e.other:QuestReward(e.self,0,0,0,0,2064); -- Pitted Iron Ring
	elseif(e.other:GetFaction(e.self) < 2 and item_lib.check_turn_in(e.trade, {item1 = 2064})) then -- Pitted Iron Ring
		e.self:Say("You have decided to wield the Naginata after all?");
		e.other:QuestReward(e.self,0,0,0,0,2097); -- Ethereal Bladed Naginata (Eldriak's Verified Naginata)
	end
	item_lib.return_items(e.self, e.other, e.trade)
end

